diff --git a/internal/vector/query/engine.go b/internal/vector/query/engine.go
index da1d216d..9714c829 100644
--- a/internal/vector/query/engine.go
+++ b/internal/vector/query/engine.go
@@ -200,7 +200,10 @@ type Response struct {
 type ResponseMetadata struct {
 	TokensUsed     int    `json:"tokens_used"`
 	IndexedHeadCKV string `json:"indexed_head_ckv"`
-	Fresh          bool   `json:"fresh"`
+	// Fresh is a best-effort hint. Normal searches return false for known
+	// source/index HEAD drift or surviving stale citations, including flow
+	// line drift. Unknown Git HEADs and dry runs do not verify freshness.
+	Fresh bool `json:"fresh"`
 	// TraceID echoes Options.TraceID (or the engine-generated fallback)
 	// so callers can correlate this response with their footprint log
 	// entries. Always set; non-empty.
@@ -864,7 +867,7 @@ func (e *Engine) Search(ctx context.Context, intent string, opts Options) (*Resp
 		Metadata: ResponseMetadata{
 			TokensUsed:     sc.TokensUsed,
 			IndexedHeadCKV: e.man.IndexedHead,
-			Fresh:          true,
+			Fresh:          stale == 0 && (currentHead == "" || e.man.IndexedHead == "" || currentHead == e.man.IndexedHead),
 			TraceID:        traceID,
 		},
 	}
